CREATE TABLE IF NOT EXISTS public.employees (
  id TEXT PRIMARY KEY,
  employee_code TEXT UNIQUE NOT NULL,
  vietnamese_name TEXT NOT NULL,
  chinese_name TEXT DEFAULT '',
  birth_year INTEGER,
  phone TEXT,
  address TEXT,
  join_date DATE,
  resign_date DATE,
  resign_reason TEXT,
  position TEXT NOT NULL,
  status TEXT NOT NULL,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.molds (
  id TEXT PRIMARY KEY,
  mold_name TEXT UNIQUE NOT NULL,
  status TEXT NOT NULL,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.orders (
  id TEXT PRIMARY KEY,
  order_code TEXT UNIQUE NOT NULL,
  mold_id TEXT REFERENCES public.molds(id) ON DELETE SET NULL,
  size TEXT,
  film_roll_name TEXT,
  completed BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.machines (
  id TEXT PRIMARY KEY,
  machine_number INTEGER UNIQUE NOT NULL,
  machine_code TEXT NOT NULL,
  machine_name TEXT,
  mold_id TEXT REFERENCES public.molds(id) ON DELETE SET NULL,
  status TEXT NOT NULL,
  current_order_id TEXT REFERENCES public.orders(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.schedules (
  date TEXT PRIMARY KEY,
  entries JSONB NOT NULL DEFAULT '{}'::jsonb,
  day_leader TEXT,
  day_team_leaders JSONB DEFAULT '[]'::jsonb,
  night_leader TEXT,
  night_team_leaders JSONB DEFAULT '[]'::jsonb,
  status TEXT DEFAULT 'SAVED',
  updated_by TEXT,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.molds ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.machines ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.schedules ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read-write employees" ON public.employees FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read-write molds" ON public.molds FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read-write orders" ON public.orders FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read-write machines" ON public.machines FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read-write schedules" ON public.schedules FOR ALL USING (true) WITH CHECK (true);

ON CONFLICT (id) DO UPDATE SET mold_name = EXCLUDED.mold_name, status = EXCLUDED.status, notes = EXCLUDED.notes;

ON CONFLICT (id) DO UPDATE SET order_code = EXCLUDED.order_code, mold_id = EXCLUDED.mold_id, size = EXCLUDED.size, film_roll_name = EXCLUDED.film_roll_name, completed = EXCLUDED.completed;

ON CONFLICT (id) DO UPDATE SET employee_code = EXCLUDED.employee_code, vietnamese_name = EXCLUDED.vietnamese_name, chinese_name = EXCLUDED.chinese_name, birth_year = EXCLUDED.birth_year, phone = EXCLUDED.phone, address = EXCLUDED.address, join_date = EXCLUDED.join_date, resign_date = EXCLUDED.resign_date, resign_reason = EXCLUDED.resign_reason, position = EXCLUDED.position, status = EXCLUDED.status;

ON CONFLICT (id) DO UPDATE SET machine_number = EXCLUDED.machine_number, mold_id = EXCLUDED.mold_id, status = EXCLUDED.status, current_order_id = EXCLUDED.current_order_id;

ON CONFLICT (date) DO UPDATE SET entries = EXCLUDED.entries, day_leader = EXCLUDED.day_leader, day_team_leaders = EXCLUDED.day_team_leaders, night_leader = EXCLUDED.night_leader, night_team_leaders = EXCLUDED.night_team_leaders, status = EXCLUDED.status;